package nl.worldmorph.npc; import java.util.*; public final class NpcManager { private final Map<UUID,NpcProfile> profiles=new LinkedHashMap<>(); public NpcProfile create(String name){NpcProfile p=new NpcProfile(UUID.randomUUID(),name);profiles.put(p.id(),p);return p;} public NpcProfile get(UUID id){return profiles.get(id);} public int size(){return profiles.size();} public Map<UUID,NpcProfile> profiles(){return Map.copyOf(profiles);} public void simulate(long tick){if(tick%1200!=0)return;for(NpcProfile p:profiles.values())if(p.alive()){p.ageOne();if(p.age()>90)p.die();}} }